import { useState, useEffect } from "react";
import { useTheme } from "../context/ThemeContext";

const navLinks = [
  { label: "About",    href: "#about" },
  { label: "Services", href: "#services" },
  { label: "Projects", href: "#projects" },
  { label: "Stack",    href: "#stack" },
  { label: "Certs",    href: "#certifications" },
  { label: "Contact",  href: "#contact" },
];

function SunIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none"
         stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
         aria-hidden="true">
      <circle cx="12" cy="12" r="5"/>
      <line x1="12" y1="1"  x2="12" y2="3"/>
      <line x1="12" y1="21" x2="12" y2="23"/>
      <line x1="4.22" y1="4.22"  x2="5.64" y2="5.64"/>
      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/>
      <line x1="1"  y1="12" x2="3"  y2="12"/>
      <line x1="21" y1="12" x2="23" y2="12"/>
      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/>
      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/>
    </svg>
  );
}

function MoonIcon() {
  return (
    <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
         stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
         aria-hidden="true">
      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>
    </svg>
  );
}

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const { theme, toggleTheme } = useTheme();

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const isDark = theme === "dark";

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? isDark
            ? "bg-ink-950/95 backdrop-blur-sm border-b border-wire"
            : "bg-white/95 backdrop-blur-sm border-b border-wire-light shadow-sm"
          : ""
      }`}
    >
      <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">

        {/* Logo */}
        <a href="#hero" className="font-mono text-sm text-accent-glow tracking-widest uppercase">
          &lt;dev /&gt;
        </a>

        {/* Desktop nav */}
        <nav className="hidden md:flex items-center gap-7">
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className={`font-body text-sm tracking-wide transition-colors duration-150 hover:text-accent-glow
                ${isDark ? "text-stone-400" : "text-gray-500 hover:text-gray-900"}`}
            >
              {link.label}
            </a>
          ))}
        </nav>

        {/* Right cluster: theme toggle + CTA */}
        <div className="hidden md:flex items-center gap-3">

          {/* ── THEME TOGGLE ────────────────────────────────────────────────
              Minimal icon button — sun = currently dark (click for light),
              moon = currently light (click for dark).
          ──────────────────────────────────────────────────────────────── */}
          <button
            onClick={toggleTheme}
            aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
            title={isDark ? "Light mode" : "Dark mode"}
            className={`w-8 h-8 flex items-center justify-center transition-colors duration-200 rounded-sm
              ${isDark
                ? "text-stone-500 hover:text-stone-200"
                : "text-gray-400 hover:text-gray-700"}`}
          >
            {isDark ? <SunIcon /> : <MoonIcon />}
          </button>

          <a
            href="#contact"
            className={`inline-flex items-center gap-2 px-4 py-2 font-mono text-xs tracking-wider transition-all duration-200
              ${isDark
                ? "border border-wire text-stone-300 hover:border-accent-dim hover:text-accent"
                : "border border-wire-light text-gray-600 hover:border-accent-glow hover:text-accent-glow"}`}
          >
            Hire Me
          </a>
        </div>

        {/* Mobile: theme toggle + hamburger */}
        <div className="md:hidden flex items-center gap-3">
          <button
            onClick={toggleTheme}
            aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
            className={`w-8 h-8 flex items-center justify-center transition-colors duration-200
              ${isDark ? "text-stone-500 hover:text-stone-200" : "text-gray-400 hover:text-gray-700"}`}
          >
            {isDark ? <SunIcon /> : <MoonIcon />}
          </button>

          <button
            className="flex flex-col gap-1.5 p-1"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Toggle menu"
          >
            <span className={`block w-5 h-px transition-all duration-200
              ${isDark ? "bg-stone-400" : "bg-gray-600"}
              ${menuOpen ? "rotate-45 translate-y-2" : ""}`} />
            <span className={`block w-5 h-px transition-all duration-200
              ${isDark ? "bg-stone-400" : "bg-gray-600"}
              ${menuOpen ? "opacity-0" : ""}`} />
            <span className={`block w-5 h-px transition-all duration-200
              ${isDark ? "bg-stone-400" : "bg-gray-600"}
              ${menuOpen ? "-rotate-45 -translate-y-2" : ""}`} />
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className={`md:hidden px-6 py-4 flex flex-col gap-4 border-b
          ${isDark ? "bg-ink-900 border-wire" : "bg-white border-wire-light"}`}>
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className={`font-body text-sm transition-colors
                ${isDark ? "text-stone-300 hover:text-accent" : "text-gray-600 hover:text-accent-glow"}`}
              onClick={() => setMenuOpen(false)}
            >
              {link.label}
            </a>
          ))}
        </div>
      )}
    </header>
  );
}
